#include <stdint.h>
#include <string.h>
#include <unistd.h>

#define DISPLAY_HAL_TAG "display_hal"

static lv_nuttx_result_t g_nuttx_result;
static bool g_display_initialized;

static bool lvgl_app_display_hal_wait_path(const char *path,
                                           uint32_t timeout_ms)
{
  uint32_t waited_ms = 0;

  if (path == NULL || path[0] == '\0')
    {
      return false;
    }

  while (access(path, F_OK) < 0)
    {
      if (waited_ms >= timeout_ms)
        {
          return false;
        }

      usleep(50u * 1000u);
      waited_ms += 50u;
    }

  return true;
}

static const char *lvgl_app_display_hal_select_fb(const char *fb_path)
{
  if (fb_path != NULL && fb_path[0] != '\0')
    {
      return fb_path;
    }

#ifdef CONFIG_LV_USE_NUTTX_LCD
  return "/dev/lcd0";
#else
  return CONFIG_LVGL_APP_HAL_DISPLAY_FB_PATH;
#endif
}

static int lvgl_app_display_hal_try_init(const char *fb_path,
                                         const char *input_path)
{
  lv_nuttx_dsc_t dsc;

  memset(&g_nuttx_result, 0, sizeof(g_nuttx_result));
  lv_nuttx_dsc_init(&dsc);
  dsc.fb_path = fb_path;
  dsc.input_path = input_path;

  LVGL_APP_LOGI(DISPLAY_HAL_TAG, "lv_nuttx_init fb=%s input=%s",
                dsc.fb_path != NULL ? dsc.fb_path : "(null)",
                dsc.input_path != NULL ? dsc.input_path : "(null)");

  lv_nuttx_init(&dsc, &g_nuttx_result);
  return g_nuttx_result.disp != NULL ? 0 : -ENODEV;
}

int lvgl_app_display_hal_init(const char *fb_path, const char *input_path)
{
  const char *primary;
  const char *fallback;
  int ret;

  if (g_display_initialized)
    {
      return 0;
    }

  if (!lv_is_initialized())
    {
      lv_init();
    }

  primary = lvgl_app_display_hal_select_fb(fb_path);
  if (!lvgl_app_display_hal_wait_path(
        primary, CONFIG_LVGL_APP_HAL_DISPLAY_DEVICE_WAIT_MS))
    {
      LVGL_APP_LOGW(DISPLAY_HAL_TAG, "display node not ready: %s",
                    primary);
    }

  ret = lvgl_app_display_hal_try_init(primary, input_path);
  if (ret < 0)
    {
      fallback = strcmp(primary, "/dev/fb0") == 0 ? "/dev/lcd0" : "/dev/fb0";
      LVGL_APP_LOGW(DISPLAY_HAL_TAG, "retry with fallback %s", fallback);
      (void)lvgl_app_display_hal_wait_path(
        fallback, CONFIG_LVGL_APP_HAL_DISPLAY_DEVICE_WAIT_MS);
      ret = lvgl_app_display_hal_try_init(fallback, input_path);
    }

  if (ret < 0)
    {
      LVGL_APP_LOGE(DISPLAY_HAL_TAG, "display init failed");
      return ret;
    }

  g_display_initialized = true;
  return 0;
}

void lvgl_app_display_hal_deinit(void)
{
  if (g_display_initialized)
    {
      lv_nuttx_deinit(&g_nuttx_result);
      g_display_initialized = false;
      memset(&g_nuttx_result, 0, sizeof(g_nuttx_result));
    }
}

lv_disp_t *lvgl_app_display_hal_get_default(void)
{
  return lv_disp_get_default();
}

