#endif

  lv_nuttx_init(&dsc, &g_lvgl_result);
  return g_lvgl_result.disp != NULL ? 0 : -ENODEV;
}

static int lvgl_app_init_display(void)
{
  const char *primary;
  const char *fallback;
  int ret;

  if (g_lvgl_ready)
    {
      return 0;
    }

  if (!lv_is_initialized())
    {
      lv_init();
    }

  primary = lvgl_app_primary_fb_path();
  if (!lvgl_app_wait_path(primary, CONFIG_LVGL_APP_HAL_DISPLAY_DEVICE_WAIT_MS))
    {
